import functools
import time


def retry(times, exceptions=(Exception,), delay=0.0, backoff=2.0, sleep=time.sleep):
    """Retry the decorated function when it raises one of ``exceptions``.

    The function is called at most ``times`` times. Before attempt ``n + 1``
    the wrapper calls ``sleep(delay * backoff ** (n - 1))`` if ``delay`` is
    non-zero. ``wrapper.last_attempts`` holds the call count of the latest run.
    """
    if times < 1:
        raise ValueError(f"times must be at least 1, got {times}")
    if delay < 0:
        raise ValueError(f"delay must be non-negative, got {delay}")
    if backoff < 1:
        raise ValueError(f"backoff must be at least 1, got {backoff}")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            wrapper.last_attempts = 0
            for attempt in range(1, times + 1):
                wrapper.last_attempts = attempt
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt == times:
                        raise
                    if delay:
                        sleep(delay * backoff ** (attempt - 1))

        wrapper.last_attempts = 0
        return wrapper

    return decorator

